for (const [language, overrides] of Object.entries(activeLocaleOverrides)) {
  dictionaries[language] = mergeDictionary(dictionaries[language], overrides);
}

function expandFlatDictionary(overrides) {
  const expanded = {};
  for (const [key, value] of Object.entries(overrides)) {
    const parts = key.split('.');
    let target = expanded;
    for (const part of parts.slice(0, -1)) {
      target[part] ??= {};
      target = target[part];
    }
    target[parts.at(-1)] = value;
  }
  return expanded;
}

for (const [language, overrides] of Object.entries(generatedLocaleOverrides)) {
  dictionaries[language] = mergeDictionary(dictionaries[language], expandFlatDictionary(overrides));
}

